function parseDate(v){
  if(v===undefined||v===null||v==='') return null;
  const s=String(v).trim();
  let m=s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})/);
  if(m){ const d=DateTime.fromObject({day:+m[1],month:+m[2],year:+m[3]},{zone:'Europe/Istanbul'}); return d.isValid?d.startOf('day'):null; }
  m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if(m){ const d=DateTime.fromObject({year:+m[1],month:+m[2],day:+m[3]},{zone:'Europe/Istanbul'}); return d.isValid?d.startOf('day'):null; }
  const d=DateTime.fromISO(s,{zone:'Europe/Istanbul'});
  return d.isValid?d.startOf('day'):null;
}
function num(v){
  if(v===undefined||v===null||v==='') return 0;
  let s=String(v).replace(/[^\d.,-]/g,'');
  if(s.indexOf(',')>-1 && s.indexOf('.')>-1){ s=s.replace(/\./g,'').replace(',', '.'); }
  else if(s.indexOf(',')>-1){ s=s.replace(',', '.'); }
  const n=parseFloat(s);
  return isNaN(n)?0:n;
}
function fmt(n){ return Number(n).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2}); }

const rows=$input.all().map(i=>i.json);
const today=$now.setZone('Europe/Istanbul').startOf('day');
const todayStr=today.toFormat('dd.MM.yyyy');
const haftaSonu=today.plus({days:7});

const ACIK=['','açık','acik','gecikti','beklemede','kısmi','kismi'];
function isAcik(d){ const s=String(d||'').trim().toLocaleLowerCase('tr-TR'); return !(s==='ödendi'||s==='odendi'||s==='iptal'||s==='kapandı'||s==='kapandi'); }

let toplamAcik=0, acikAdet=0;
let toplamGecikmis=0, gecikmisAdet=0;
let toplamBuHafta=0, buHaftaAdet=0;
let bugunTahsil=0, bugunTahsilAdet=0;
const gecikmisler=[];

for(const r of rows){
  const tutar=num(r.tutar);
  const vade=parseDate(r.vade_tarihi);
  const odeme=parseDate(r.odeme_tarihi);
  const durumStr=String(r.durum||'').trim().toLocaleLowerCase('tr-TR');

  if((durumStr==='ödendi'||durumStr==='odendi') && odeme && +odeme===+today){
    bugunTahsil+=tutar; bugunTahsilAdet++;
  }
  if(isAcik(r.durum)){
    toplamAcik+=tutar; acikAdet++;
    if(vade && vade < today){
      const g=Math.round(today.diff(vade,'days').days);
      toplamGecikmis+=tutar; gecikmisAdet++;
      gecikmisler.push({fatura:r.fatura_no,musteri:r.musteri,tutar,pb:r.para_birimi||'TL',gun:g});
    } else if(vade && vade>=today && vade<=haftaSonu){
      toplamBuHafta+=tutar; buHaftaAdet++;
    }
  }
}

gecikmisler.sort((a,b)=>b.tutar-a.tutar);
const top=gecikmisler.slice(0,5).map(x=>`   • ${x.fatura} — ${x.musteri} — ${fmt(x.tutar)} ${x.pb} — ${x.gun} gün`).join('\n') || '   —';

const body=
`MirFix Günlük Tahsilat Raporu — ${todayStr}\n`+
`====================================\n\n`+
`💰 Bugün tahsil edilen: ${fmt(bugunTahsil)} TL (${bugunTahsilAdet} fatura)\n`+
`📂 Toplam açık alacak: ${fmt(toplamAcik)} TL (${acikAdet} fatura)\n`+
`🔴 Gecikmiş alacak: ${fmt(toplamGecikmis)} TL (${gecikmisAdet} fatura)\n`+
`📅 Bu hafta vadesi gelen: ${fmt(toplamBuHafta)} TL (${buHaftaAdet} fatura)\n\n`+
`En büyük 5 gecikmiş alacak:\n${top}\n\n`+
(gecikmisAdet===0 ? 'Gecikmiş alacak yok. 👍\n' : '')+
`Bu rapor otomatik üretilmiştir.`;

return [{ json:{ rapor_konu:`MirFix Tahsilat Raporu — ${todayStr}`, rapor_metni:body } }];
